func (q *Queries) PeerIntentsPurge(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, peerIntentsPurge, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const peerIntentsUnavailable = `-- name: PeerIntentsUnavailable :many
SELECT entity_id, uss_base_url, time_end
FROM peer_intents
WHERE peer_unavailable AND time_end >= now()
ORDER BY entity_id
LIMIT $1
`

type PeerIntentsUnavailableRow struct {
	EntityID   string     `json:"entity_id"`
	UssBaseUrl string     `json:"uss_base_url"`
	TimeEnd    *time.Time `json:"time_end"`
}

// The peers' intents of a window, with their mark, for the peer view.
func (q *Queries) PeerIntentsUnavailable(ctx context.Context, maxRows int32) ([]PeerIntentsUnavailableRow, error) {
	rows, err := q.db.Query(ctx, peerIntentsUnavailable, maxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []PeerIntentsUnavailableRow
	for rows.Next() {
		var i PeerIntentsUnavailableRow
		if err := rows.Scan(&i.EntityID, &i.UssBaseUrl, &i.TimeEnd); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

