const subscriptionNotified = `-- name: SubscriptionNotified :one
UPDATE dss_subscriptions s
SET notification_index = GREATEST(s.notification_index, $1::integer)
FROM (SELECT d.subscription_id AS sid, d.notification_index AS previous
      FROM dss_subscriptions d
      WHERE d.subscription_id = $2
      FOR UPDATE) old
WHERE s.subscription_id = old.sid
RETURNING old.previous::integer AS previous
`

type SubscriptionNotifiedParams struct {
	Idx            int32  `json:"idx"`
	SubscriptionID string `json:"subscription_id"`
}

// The notification index of one of our subscriptions, advanced to idx;
// the index held before, and false when the subscription is not ours.
func (q *Queries) SubscriptionNotified(ctx context.Context, arg SubscriptionNotifiedParams) (int32, error) {
	row := q.db.QueryRow(ctx, subscriptionNotified, arg.Idx, arg.SubscriptionID)
	var previous int32
	err := row.Scan(&previous)
	return previous, err
}

const subscriptionUpsert = `-- name: SubscriptionUpsert :exec
INSERT INTO dss_subscriptions (subscription_id, kind, area, version, notification_index, time_end, uss_base_url, renewed_at)
VALUES ($1, 'utm', $2, $3, $4,
        $5, $6, now())
ON CONFLICT (subscription_id) DO UPDATE
SET area = EXCLUDED.area, version = EXCLUDED.version,
    notification_index = GREATEST(dss_subscriptions.notification_index, EXCLUDED.notification_index),
    time_end = EXCLUDED.time_end, uss_base_url = EXCLUDED.uss_base_url, renewed_at = now()
`

type SubscriptionUpsertParams struct {
	SubscriptionID    string    `json:"subscription_id"`
	Area              []byte    `json:"area"`
	Version           *string   `json:"version"`
	NotificationIndex int32     `json:"notification_index"`
	TimeEnd           time.Time `json:"time_end"`
	UssBaseUrl        string    `json:"uss_base_url"`
}

func (q *Queries) SubscriptionUpsert(ctx context.Context, arg SubscriptionUpsertParams) error {
	_, err := q.db.Exec(ctx, subscriptionUpsert,
		arg.SubscriptionID,
		arg.Area,
		arg.Version,
		arg.NotificationIndex,
		arg.TimeEnd,
		arg.UssBaseUrl,
	)
	return err
}

